#[must_use]
pub fn earth_moon_lab_bodies() -> Vec<CanonicalBodySpec> {
    // Horizons physical-summary GM values are divided by the solver's G.
    // This preserves the intended gravitational parameters without mass rounding.
    const G: f64 = 6.67430e-11;
    let metadata = [
        (
            "sun",
            BodyClass::Star,
            132712440041.93938 * 1.0e9 / G,
            696340000.0,
        ),
        (
            "earth",
            BodyClass::Planet,
            398600.435436 * 1.0e9 / G,
            6371010.0,
        ),
        ("moon", BodyClass::Moon, 4902.800066 * 1.0e9 / G, 1737400.0),
    ];
    metadata
        .into_iter()
        .enumerate()
        .map(|(index, (body_id, body_class, mass_kg, radius_m))| {
            let p = EARTH_MOON_REFERENCE_EPOCHS[0].positions_m[index];
            let v = EARTH_MOON_REFERENCE_EPOCHS[0].velocities_mps[index];
            CanonicalBodySpec {
                body_id: body_id.into(),
                body_class,
                mass_kg,
                radius_m,
                position_m: Vector3d {
                    x: p[0],
                    y: p[1],
                    z: p[2],
                },
                velocity_mps: Vector3d {
                    x: v[0],
                    y: v[1],
                    z: v[2],
                },
            }
        })
        .collect()
}
